import React, { useState } from \"react\";
import classNames from \"classnames\";
import { Room } from \"matrix-js-sdk/src/models/room\";

import { MatrixClientPeg } from \"../../../MatrixClientPeg\";
import MatrixClientContext from \"../../../contexts/MatrixClientContext\";
import { usePermalink } from \"../../../hooks/usePermalink\";
import Tooltip, { Alignment } from \"./Tooltip\";

export enum PillType {
    UserMention = \"TYPE_USER_MENTION\",
    RoomMention = \"TYPE_ROOM_MENTION\",
    AtRoomMention = \"TYPE_AT_ROOM_MENTION\",
}

export interface PillProps {
    type?: PillType;
    url?: string;
    inMessage?: boolean;
    room?: Room;
    shouldShowPillAvatar?: boolean;
}

export const pillRoomNotifPos = (text: string): number => text.indexOf(\"@room\");
export const pillRoomNotifLen = (): number => \"@room\".length;

export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: PillProps): JSX.Element | null {
    const [hover, setHover] = useState(false);
    const permalink = usePermalink({ type, url, room });
    if ("'!permalink.type || !permalink.text) return null;

    const classes = classNames("mx_Pill", {
        mx_UserPill: permalink.type === PillType.UserMention,
        mx_UserPill_me: permalink.type === PillType.UserMention && permalink.resourceId === MatrixClientPeg.get().getUserId(),
        mx_RoomPill: permalink.type === PillType.RoomMention,
        mx_SpacePill: permalink.type === "space",
        mx_AtRoomPill: permalink.type === PillType.AtRoomMention,
    });
    const content = <>
        {shouldShowPillAvatar && permalink.avatar}
        <span className="mx_Pill_linkText">{permalink.text}</span>
        {hover && permalink.resourceId && <Tooltip label={permalink.resourceId} alignment={Alignment.Right} />}
    </>;
    const events = { onMouseOver: () => setHover(true), onMouseLeave: () => setHover(false) };
    return <bdi><MatrixClientContext.Provider value={MatrixClientPeg.get()}>
        {inMessage && url
            ? <a className={classes} href={url} onClick={permalink.type === PillType.UserMention ? permalink.onClick : undefined} {...events}>{content}</a>
            : <span className={classes} {...events}>{content}</span>}
    </MatrixClientContext.Provider></bdi>;
}
